"""Generator v3 grooming: eyebrows, eyelashes and one hairstyle as strand ribbons generated by Forge.

Every strand is anchored to a body triangle (barycentric root). The studio re-evaluates the strands from the live body
after every edit, so they follow all controls, the blink (lashes ride the lid) and skinning, with no per-control morph
data:

- ``frame`` anchors (brows, lashes): offsets in the root triangle's local frame (t = b - a, n = face normal,
  b = n x t), so the hair turns with the skin under it (lashes close with the lid);
- ``cage`` anchors (scalp hair): every strand point follows a weighted blend of the displacements of nearby skin
  vertices (roots: exactly their triangle), so the hair widens and narrows with the head, jaw, neck and shoulders and
  long strands do not swing.

Hair is many thin ribbons (several hairs each, alpha from a strand profile), not a solid shell.
"""

from __future__ import annotations

from functools import lru_cache

import numpy as np

from forge_character_forge.v3 import mh, model, rig, textures

HAIR_STRANDS = 3400
HAIR_POINTS = 14


def _frame(P, tri):
    a, b, c = P[tri[:, 0]], P[tri[:, 1]], P[tri[:, 2]]
    t = b - a
    t /= np.linalg.norm(t, axis=1, keepdims=True)
    n = np.cross(b - a, c - a)
    n /= np.linalg.norm(n, axis=1, keepdims=True)
    return t, np.cross(n, t), n


def _vertex_normals(P, tris):
    fn = np.cross(P[tris[:, 1]] - P[tris[:, 0]], P[tris[:, 2]] - P[tris[:, 0]])
    n = np.zeros_like(P)
    for k in range(3):
        np.add.at(n, tris[:, k], fn)
    return n / np.maximum(np.linalg.norm(n, axis=1, keepdims=True), 1e-12)


@lru_cache(maxsize=None)
def surface():
    """Body split-vertex positions, triangles, vertex normals (welded across UV seams), base ids."""
    v = model.neutral()
    src, _, tris, weld = model.body_surface()
    P = v[src]
    n = _vertex_normals(v, src[tris])[src]
    return P, tris, n, src


def _ribbons(polys, widths, side_dirs):
    """Strips: polys (S,K,3), widths (S,K), side_dirs (S,K,3) -> verts (S*K*2,3), uv, tris."""
    S, K, _ = polys.shape
    L = polys - side_dirs * widths[:, :, None] / 2
    R = polys + side_dirs * widths[:, :, None] / 2
    verts = np.stack([L, R], 2).reshape(-1, 3)
    u = np.repeat(np.linspace(0, 1, K)[None, :], S, 0)
    uv = np.stack([np.stack([u, np.zeros_like(u)], 2), np.stack([u, np.ones_like(u)], 2)], 2).reshape(-1, 2)
    base = (np.arange(S) * K * 2)[:, None] + (np.arange(K - 1) * 2)[None, :]
    q = base.reshape(-1)
    tris = np.concatenate([np.stack([q, q + 1, q + 2], 1), np.stack([q + 1, q + 3, q + 2], 1)])
    return verts, uv, tris


def _anchor(verts_per_strand, root_tri, root_bary, mode):
    """Offsets of strand vertices relative to their root, in the anchor's frame."""
    P, *_ = surface()
    S = len(root_tri)
    V = verts_per_strand.reshape(S, -1, 3)
    root = (P[root_tri] * root_bary[:, :, None]).sum(1)
    rel = V - root[:, None, :]
    if mode == "frame":
        t, b, n = _frame(P, root_tri)
        rel = np.stack([(rel * t[:, None]).sum(2), (rel * b[:, None]).sum(2), (rel * n[:, None]).sum(2)], 2)
    return rel.reshape(-1, 3)


def _skin_from_roots(root_tri, root_bary, per_strand):
    """Skin weights of each strand = its root's interpolated body weights (top four)."""
    v = model.neutral()
    J, W, _ = rig.skin(len(v))
    _, _, _, src = surface()
    acc = np.zeros((len(root_tri), len(rig.NAMES)))
    for c in range(3):
        for k in range(4):
            np.add.at(acc, (np.arange(len(root_tri)), J[src[root_tri[:, c]], k]), W[src[root_tri[:, c]], k] * root_bary[:, c])
    order = np.argsort(-acc, 1)[:, :4]
    w = np.take_along_axis(acc, order, 1)
    w /= w.sum(1, keepdims=True)
    return np.repeat(order, per_strand, 0), np.repeat(w, per_strand, 0)


def _project_front(xy, z_min, cand_tris):
    """Project (N,2) points along -z onto the body: (triangle index, barycentrics, 3D point) per point."""
    P, tris, _, _ = surface()
    T = tris[cand_tris]
    a, b, c = P[T[:, 0]], P[T[:, 1]], P[T[:, 2]]
    out_t, out_b, out_p = [], [], []
    d = (b[:, 1] - c[:, 1]) * (a[:, 0] - c[:, 0]) + (c[:, 0] - b[:, 0]) * (a[:, 1] - c[:, 1])
    d = np.where(np.abs(d) < 1e-14, np.inf, d)  # edge-on triangles never contain a point
    for x, y in xy:
        w0 = ((b[:, 1] - c[:, 1]) * (x - c[:, 0]) + (c[:, 0] - b[:, 0]) * (y - c[:, 1])) / d
        w1 = ((c[:, 1] - a[:, 1]) * (x - c[:, 0]) + (a[:, 0] - c[:, 0]) * (y - c[:, 1])) / d
        w2 = 1 - w0 - w1
        ok = (w0 >= 0) & (w1 >= 0) & (w2 >= 0)
        z = w0 * a[:, 2] + w1 * b[:, 2] + w2 * c[:, 2]
        z = np.where(ok & (z > z_min), z, -np.inf)
        k = int(np.argmax(z))
        bary = np.array([w0[k], w1[k], w2[k]])
        out_t.append(cand_tris[k])
        out_b.append(bary)
        out_p.append((P[T[k]] * bary[:, None]).sum(0))
    return np.array(out_t), np.array(out_b), np.array(out_p)


# ---------------------------------------------------------------- eyebrows
def eyebrows(seed: int = 11):
    v = model.neutral()
    E, (cl, cr) = textures.head_frame_v3(v)
    P, tris, nrm, src = surface()
    rng = np.random.default_rng(seed)
    cent = P[tris].mean(1)
    cand = np.nonzero((cent[:, 2] > E[2] - 0.01) & (np.abs(cent[:, 1] - E[1] - 0.02) < 0.03) & (np.abs(cent[:, 0]) < 0.08))[0]
    polys, widths, sides, roots_t, roots_b = [], [], [], [], []
    for c, sgn in ((cl, 1.0), (cr, -1.0)):
        n_h = 520
        t = rng.random(n_h) ** 0.85                                  # denser toward the head of the brow
        x = c[0] - sgn * 0.017 + sgn * 0.047 * t                     # inner end over the inner canthus, tail past the outer corner
        arch = np.where(t < 0.66, np.sin(np.pi / 2 * t / 0.66), 1 - 0.55 * np.clip((t - 0.66) / 0.34, 0, 1) ** 1.5)
        mid = c[1] + 0.0175 + 0.0065 * arch
        thick = 0.0068 * (1 - t) + 0.0024 * t
        y = mid + (rng.random(n_h) - 0.5) * thick
        tri, bary, root = _project_front(np.stack([x, y], 1), E[2] - 0.02, cand)
        for i in range(n_h):
            n = nrm[tris[tri[i]]].T @ bary[i]
            n /= np.linalg.norm(n)
            # growth: up and out at the head of the brow, then along the brow and slightly down at the tail
            ang = np.radians(np.interp(t[i], [0, 0.18, 0.5, 1], [62, 30, 8, -16]) + rng.normal(0, 5))
            g = np.array([sgn * np.cos(ang), np.sin(ang), 0.0])
            g -= n * (g @ n)
            g /= np.linalg.norm(g)
            L = np.interp(t[i], [0, 0.3, 1], [0.0048, 0.0062, 0.0042]) * (0.8 + 0.4 * rng.random())
            k = np.linspace(0, 1, 4)[:, None]
            lift = n * (0.00025 + 0.0011 * k * (1 - 0.6 * k))           # leaves the skin at a shallow angle, then lies down
            pts = root[i] + g * L * k + lift
            polys.append(pts)
            widths.append(np.array([0.00038, 0.00034, 0.00024, 0.0001]))
            sides.append(np.repeat(np.cross(n, g)[None], 4, 0))
            roots_t.append(tri[i])
            roots_b.append(bary[i])
    return _strand_part(np.array(polys), np.array(widths), np.array(sides), np.array(roots_t), np.array(roots_b), "frame", "brow")


# ---------------------------------------------------------------- eyelashes
def _lid_margins():
    """Per eye: ordered base-vertex ids of the upper and lower lid margins, inner corner to outer corner.

    hm08's skin is closed: past the visible lid edge it continues inside the eyeball, hidden. The visible margin is
    therefore the ring of lid vertices outside the cornea sphere with a neighbour inside it."""
    v = model.neutral()
    _, cs = textures.head_frame_v3(v)
    nb = model._neighbours()
    out = {}
    for side, c in zip("lr", cs):
        cc, R = model.sphere_fit(mh.fit_eyes(v)[model.eye_parts()[f"cornea_{side}"][0]])
        dist = np.linalg.norm(v - cc, axis=1)
        reg = model.lid_region(side, 2)
        ring = np.array([i for i in reg if v[i, 2] > c[2] and dist[i] >= R * 0.995
                         and any(dist[j] < R * 0.995 for j in nb[int(i)])])
        q = v[ring] - c
        sgn = 1.0 if side == "l" else -1.0
        xs = q[:, 0] * sgn
        i_in, i_out = np.argmin(xs), np.argmax(xs)
        for upper in (True, False):
            line = np.interp(xs, [xs[i_in], xs[i_out]], [q[i_in, 1], q[i_out, 1]])
            m = (q[:, 1] >= line) if upper else (q[:, 1] <= line)
            m[[i_in, i_out]] = True
            sel, qx, qy = ring[m], xs[m], q[m, 1]
            bins = np.floor((qx - xs[i_in]) / (xs[i_out] - xs[i_in] + 1e-9) * 13).astype(int)
            keep = [np.nonzero(bins == b)[0][np.argmin(qy[bins == b] * (1 if upper else -1))] for b in np.unique(bins)]
            sel = np.unique(np.r_[sel[keep], ring[[i_in, i_out]]])  # closest to the opening per x bin, plus corners
            out[(side, upper)] = sel[np.argsort(sgn * (v[sel, 0] - c[0]))]
    return out, cs


def eyelashes(seed: int = 12):
    v = model.neutral()
    P, tris, nrm, src = surface()
    margins, cs = _lid_margins()
    rng = np.random.default_rng(seed)
    lid = set(np.concatenate([model.lid_region(s, 2) for s in "lr"]).tolist())
    lid_tris = np.array([t for t, tri in enumerate(tris) if all(int(src[x]) in lid for x in tri)])
    polys, widths, sides, roots_t, roots_b = [], [], [], [], []
    for side, c in zip("lr", cs):
        for upper in (True, False):
            seq = margins[(side, upper)]
            mp = v[seq].copy()
            med = np.array([np.median(mp[max(i - 1, 0):i + 2, 1]) for i in range(len(mp))])
            ok = np.abs(mp[:, 1] - med) < 0.0012           # drop vertices that stray off the lid line
            ok[[0, -1]] = True
            seq, mp = seq[ok], mp[ok]
            seg = np.r_[0, np.cumsum(np.linalg.norm(np.diff(mp, axis=0), axis=1))]
            count = 110 if upper else 30
            for i in range(count):
                tt = (i + 0.5 + 0.3 * rng.random()) / count
                if upper and tt < 0.08:
                    continue
                s = np.interp(tt, seg / seg[-1], np.arange(len(mp)))
                j = min(int(s), len(mp) - 2)
                f = s - j
                root = mp[j] * (1 - f) + mp[j + 1] * f
                tri, bary, root = _closest_on(root, lid_tris)  # the root lies on the skin, not on a chord
                out = root - c
                out[2] = max(out[2], 0.0)
                out /= np.linalg.norm(out)
                up = np.array([0, 1.0 if upper else -1.0, 0])
                d0 = (np.array([0, 0, 1.0]) * 0.75 + up * 0.55 + out * 0.25)
                d0 /= np.linalg.norm(d0)
                L = (np.interp(tt, [0, 0.35, 0.8, 1], [0.0065, 0.0095, 0.0105, 0.0075]) if upper else
                     np.interp(tt, [0, 0.5, 1], [0.0018, 0.0032, 0.0026])) * (0.85 + 0.3 * rng.random())
                curl = 0.45 if upper else 0.2   # the lash bends toward ``up`` along its length
                pts, q = [root + 0.0003 * np.array([0, 0, 1.0])], root + 0.0003 * np.array([0, 0, 1.0])
                for k5 in range(4):
                    d = d0 + up * curl * (k5 + 0.5) / 4
                    q = q + d / np.linalg.norm(d) * L / 4
                    pts.append(q.copy())
                pts = np.array(pts)
                polys.append(pts)
                widths.append(np.array([0.00024, 0.00022, 0.00017, 0.0001, 0.00004]))
                sd = np.cross(np.gradient(pts, axis=0), np.array([0, 0, 1.0]))
                sd /= np.maximum(np.linalg.norm(sd, axis=1, keepdims=True), 1e-9)
                sides.append(sd)
                roots_t.append(tri)
                roots_b.append(bary)
    return _strand_part(np.array(polys), np.array(widths), np.array(sides), np.array(roots_t), np.array(roots_b), "frame", "lash")


# ---------------------------------------------------------------- hair: shoulder-length layers, side part
def hair(seed: int = 13):
    v = model.neutral()
    E, _ = textures.head_frame_v3(v)
    P, tris, nrm, src = surface()
    rng = np.random.default_rng(seed)
    # roots: area-weighted samples on the scalp
    sm = textures.scalp_mask(v)[src]
    w = sm[tris].mean(1)
    area = np.linalg.norm(np.cross(P[tris[:, 1]] - P[tris[:, 0]], P[tris[:, 2]] - P[tris[:, 0]]), axis=1) / 2
    prob = area * (w > 0.5)
    tri = rng.choice(len(tris), HAIR_STRANDS, p=prob / prob.sum())
    r1, r2 = rng.random(HAIR_STRANDS), rng.random(HAIR_STRANDS)
    s1 = np.sqrt(r1)
    bary = np.stack([1 - s1, s1 * (1 - r2), s1 * r2], 1)
    root = (P[tris[tri]] * bary[:, :, None]).sum(1)
    rn = (nrm[tris[tri]] * bary[:, :, None]).sum(1)
    rn /= np.linalg.norm(rn, axis=1, keepdims=True)
    # collision body: upper body vertices with normals
    up = v[model.body_vertex_ids()]
    upn = _vertex_normals(v, src[tris])[model.body_vertex_ids()]
    keep = up[:, 1] > E[1] - 0.45
    up, upn = up[keep], upn[keep]
    up32, uu = up.astype(np.float32), (up * up).sum(1).astype(np.float32)
    rel = root - E
    part_x = 0.022                                                   # side part, on the character's left
    side = np.where(rel[:, 0] > part_x, 1.0, -1.0)
    back = np.clip(-rel[:, 2] / 0.08, 0, 1)
    comb = np.stack([side * (1 - back) ** 2, -0.25 - 0.9 * back, -0.35 * (1 - back) - 0.4 * back], 1)
    nape = np.clip(-rel[:, 1] / 0.04, 0, 1) * back  # low at the back: straight down and away from the neck
    comb = comb * (1 - nape[:, None]) + np.array([0, -1.0, -0.45]) * nape[:, None]
    lift = 0.0015 + 0.006 * rng.random(HAIR_STRANDS) ** 0.7           # layer height above the scalp (volume)
    theta = np.degrees(np.arctan2(rel[:, 0], rel[:, 2]))
    tip_y = E[1] + np.interp(np.abs(theta), [0, 60, 120, 180], [-0.135, -0.15, -0.165, -0.17]) + rng.normal(0, 0.01, HAIR_STRANDS)
    step = 0.009
    pts = [root.copy()]
    d = comb - rn * np.minimum((comb * rn).sum(1, keepdims=True), 0)  # only the into-scalp part is removed
    d /= np.linalg.norm(d, axis=1, keepdims=True)
    p = root + rn * lift[:, None] * 0.5
    alive = np.ones(HAIR_STRANDS, bool)
    for k in range(60):
        g = np.array([0, -1.0, 0]) * min(1.0, 0.25 + k * 0.06)
        d = d + g * 0.35
        d /= np.linalg.norm(d, axis=1, keepdims=True)
        if k < 10:  # near the root the hair lies along the scalp (no spikes)
            dist0 = (p * p).sum(1)[:, None] - 2 * p.astype(np.float32) @ up32.T + uu[None, :]
            n0 = upn[np.argmin(dist0, 1)]
            cap = np.where(n0[:, 1] > -0.2, 0.15, 1.0)  # where the scalp faces down, hair falls free
            d = d - n0 * np.minimum((d * n0).sum(1), cap)[:, None]
            d /= np.linalg.norm(d, axis=1, keepdims=True)
        q = p + d * step
        # keep clear of the body: nearest upper-body vertex, push out along its normal
        dist = (q * q).sum(1)[:, None] - 2 * q.astype(np.float32) @ up32.T + uu[None, :]
        nn = np.argmin(dist, 1)
        sd = ((q - up[nn]) * upn[nn]).sum(1)
        need = lift + 0.002
        push = sd < need
        q[push] += upn[nn[push]] * (need[push] - sd[push])[:, None]
        # keep the face clear
        r = q - E
        face = (r[:, 2] > -0.005) & (np.abs(r[:, 0]) < 0.068) & (r[:, 1] < 0.05) & (r[:, 1] > -0.14)
        q[face, 0] = E[0] + np.sign(r[face, 0] + 1e-9) * (0.068 + lift[face])
        d = (q - p)
        d /= np.maximum(np.linalg.norm(d, axis=1, keepdims=True), 1e-9)
        p = np.where(alive[:, None], q, p)
        alive &= p[:, 1] > tip_y
        pts.append(p.copy())
    pts = np.stack(pts, 1)  # (S, 61, 3); finished strands repeat their last point
    seg = np.linalg.norm(np.diff(pts, axis=1), axis=2)
    cum = np.concatenate([np.zeros((HAIR_STRANDS, 1)), np.cumsum(seg, 1)], 1)
    polys = np.zeros((HAIR_STRANDS, HAIR_POINTS, 3))
    for i in range(HAIR_STRANDS):
        s = np.linspace(0, cum[i, -1], HAIR_POINTS)
        for c in range(3):
            polys[i, :, c] = np.interp(s, cum[i], pts[i, :, c])
    for _ in range(3):  # smooth (roots fixed)
        polys[:, 1:-1] = polys[:, 1:-1] * 0.5 + (polys[:, :-2] + polys[:, 2:]) * 0.25
    # clumps: strands gather toward their clump's mean path toward the ends (locks, not a uniform sheet)
    u = np.linspace(0, 1, HAIR_POINTS)
    clump = _nearest_centres(root, 240, rng)
    for c_id in np.unique(clump):
        m = clump == c_id
        mean = polys[m].mean(0)
        pull = 0.55 * u[None, :, None] ** 1.2
        polys[m] = polys[m] * (1 - pull) + mean[None] * pull
    # a gentle wave per clump, perpendicular to the strand, growing toward the ends
    phase = rng.random(240)[clump]
    tang0 = np.gradient(polys, axis=1)
    perp = np.cross(tang0, polys - E)
    perp /= np.maximum(np.linalg.norm(perp, axis=2, keepdims=True), 1e-9)
    wave = 0.0028 * np.sin(2 * np.pi * (u[None, :] * 2.3 + phase[:, None])) * u[None, :] ** 0.8
    polys += perp * wave[:, :, None]
    # ends turn slightly under, toward the neck
    axis = np.array([E[0], 0, E[2] - 0.05])
    inward = axis[None, None, :] - polys * np.array([1, 0, 1])
    inward[:, :, 1] = 0
    inward /= np.maximum(np.linalg.norm(inward, axis=2, keepdims=True), 1e-9)
    back_w = np.clip((np.abs(theta) - 100) / 40, 0, 1)[:, None, None]  # only behind the ears: nothing tucks under the chin
    polys += inward * back_w * (0.012 * np.clip((u - 0.75) / 0.25, 0, 1) ** 2)[None, :, None]
    # the face stays clear after clumping and waving too
    r = polys - E
    face = (r[:, :, 2] > -0.012) & (np.abs(r[:, :, 0]) < 0.07) & (r[:, :, 1] < 0.045) & (r[:, :, 1] > -0.22)
    face[:, 0] = False  # roots never move
    polys[:, :, 0] = np.where(face, E[0] + np.sign(r[:, :, 0] + 1e-9) * (0.07 + lift[:, None]), polys[:, :, 0])
    # drop the rare strand that still ends up in front of the face or neck
    r = polys - E
    stray = ((r[:, :, 2] > -0.07) & (np.abs(r[:, :, 0]) < 0.05) & (r[:, :, 1] < -0.08)).any(1)
    polys, tri, bary, lift = polys[~stray], tri[~stray], bary[~stray], lift[~stray]
    rng_w = rng.random(len(polys))
    tang = np.gradient(polys, axis=1)
    radial = polys - E
    sd = np.cross(tang, radial)
    sd /= np.maximum(np.linalg.norm(sd, axis=2, keepdims=True), 1e-9)
    widths = (0.0042 + 0.0025 * rng_w)[:, None] * (1 - 0.55 * u ** 1.5)[None]
    part = _strand_part(polys, widths, sd, tri, bary, "cage", "hair")
    part["anchor"].update(_cage(polys, tris[tri], bary))
    # per-strand shading tint: inner layers darker (self-shadowing), slight per-strand variation
    tint = (0.55 + 0.45 * (lift - lift.min()) / np.ptp(lift)) * (0.9 + 0.2 * rng.random(len(polys)))
    part["color"] = np.repeat(np.repeat(tint, HAIR_POINTS * 2)[:, None], 3, 1)
    return part


def _closest_on(p, cand):
    """Closest point on the body surface (among candidate split triangles): (triangle, barycentrics, point)."""
    P, tris, _, _ = surface()
    T = tris[cand]
    a, b, c = P[T[:, 0]], P[T[:, 1]], P[T[:, 2]]
    best = None
    for k in range(len(cand)):
        e0, e1 = b[k] - a[k], c[k] - a[k]
        M = np.array([[e0 @ e0, e0 @ e1], [e0 @ e1, e1 @ e1]])
        try:
            s, t = np.linalg.solve(M, [e0 @ (p - a[k]), e1 @ (p - a[k])])
        except np.linalg.LinAlgError:
            continue
        s, t = max(s, 0.0), max(t, 0.0)
        if s + t > 1:
            s, t = s / (s + t), t / (s + t)
        q = a[k] + s * e0 + t * e1
        d = np.linalg.norm(q - p)
        if best is None or d < best[0]:
            best = (d, cand[k], np.array([1 - s - t, s, t]), q)
    return best[1], best[2], best[3]


CAGE_K = 6


def _cage(polys, root_tri, root_bary):
    """Per strand point: CAGE_K skin vertices (split-surface ids) and weights. The root point uses its triangle;
    the others the nearest head/neck/shoulder vertices, inverse-distance weighted."""
    P, _, _, _ = surface()
    S, K, _ = polys.shape
    v = model.neutral()
    E, _ = textures.head_frame_v3(v)
    near = np.nonzero(P[:, 1] > E[1] - 0.4)[0]
    Q = P[near].astype(np.float32)
    qq = (Q * Q).sum(1)
    pts = polys.reshape(-1, 3)
    idx = np.zeros((len(pts), CAGE_K), np.int64)
    w = np.zeros((len(pts), CAGE_K))
    for a in range(0, len(pts), 4096):
        x = pts[a:a + 4096].astype(np.float32)
        d2 = (x * x).sum(1)[:, None] - 2 * x @ Q.T + qq[None]
        nn = np.argpartition(d2, CAGE_K, 1)[:, :CAGE_K]
        dd = np.sqrt(np.maximum(np.take_along_axis(d2, nn, 1), 1e-12))
        ww = 1 / (dd + 0.004) ** 2
        idx[a:a + 4096] = near[nn]
        w[a:a + 4096] = ww / ww.sum(1, keepdims=True)
    roots = np.arange(S) * K
    idx[roots] = 0
    w[roots] = 0
    idx[roots, :3] = root_tri
    w[roots, :3] = root_bary
    return {"cage_idx": idx, "cage_w": w}


def _nearest_centres(p, k, rng):
    """Cluster labels: each point joins its nearest of k centres sampled from the points (deterministic rng)."""
    cen = p[rng.choice(len(p), k, replace=False)]
    return np.argmin(((p[:, None, :] - cen[None]) ** 2).sum(2), 1)


def _strand_part(polys, widths, sides, root_tri, root_bary, mode, kind):
    P, tris, _, _ = surface()
    S, K, _ = polys.shape
    verts, uv, t = _ribbons(polys, widths, sides)
    off = _anchor(verts, tris[root_tri], root_bary, mode)
    j, w = _skin_from_roots(tris[root_tri], root_bary, K * 2)
    return {"pos": verts, "uv": uv, "tris": t, "joints": j, "weights": w, "strands": S, "points": K,
            "anchor": {"mode": mode, "root": np.repeat(np.arange(S), K * 2), "tri": tris[root_tri], "bary": root_bary, "off": off},
            "kind": kind}


@lru_cache(maxsize=None)
def parts() -> dict:
    return {"brows": eyebrows(), "lashes": eyelashes(), "hair_shoulder": hair()}
